import{_ as a}from"./chunks/esc_pwm_duty_cycle.g-RjqZ-y.js";import{_ as o,o as r,c as t,al as s}from"./chunks/framework.7vp1BMOE.js";const m=JSON.parse('{"title":"ESC Protocols","description":"","frontmatter":{},"headers":[],"relativePath":"zh/esc/esc_protocols.md","filePath":"zh/esc/esc_protocols.md"}'),i={name:"zh/esc/esc_protocols.md"};function n(h,e,l,c,p,d){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="esc-protocols" tabindex="-1">ESC Protocols <a class="header-anchor" href="#esc-protocols" aria-label="Permalink to &quot;ESC Protocols&quot;">​</a></h1><p>This topic lists the main <a href="./../peripherals/esc_motors">Electronic Speed Controller (ESC)</a> protocols supported by PX4.</p><h2 id="dshot" tabindex="-1">DShot <a class="header-anchor" href="#dshot" aria-label="Permalink to &quot;DShot&quot;">​</a></h2><p><a href="./../peripherals/dshot">DShot</a> is a digital ESC protocol that is highly recommended for vehicles that can benefit from reduced latency, in particular racing multicopters, VTOL vehicles, and so on.</p><p>It has reduced latency and is more robust than both <a href="#pwm">PWM</a> and <a href="#oneshot-125">OneShot</a>. In addition it does not require ESC calibration, telemetry is available from some ESCs, and you can reverse motor spin directions.</p><p>PX4 configuration is done in the <a href="./../config/actuators">Actuator Configuration</a>. Selecting a higher rate DShot ESC in the UI results in lower latency, but lower rates are more robust (and hence more suitable for large aircraft with longer leads); some ESCs only support lower rates (see datasheets for information).</p><p>Setup:</p><ul><li><a href="./../peripherals/pwm_escs_and_servo">ESC Wiring</a> (same as for PWM ESCs)</li><li><a href="./../peripherals/dshot">DShot</a> also contains information about how to send commands etc.</li></ul><h2 id="dronecan" tabindex="-1">DroneCAN <a class="header-anchor" href="#dronecan" aria-label="Permalink to &quot;DroneCAN&quot;">​</a></h2><p><a href="./../dronecan/escs">DroneCAN ESCs</a> are recommended when DroneCAN is the primary bus used for your vehicle. The PX4 implementation is currently limited to update rates of 200 Hz.</p><p>DroneCAN shares many similar benefits to <a href="#dshot">DShot</a> including high data rates, robust connection over long leads, telemetry feedback, no need for calibration of the ESC itself.</p><p><a href="./../dronecan/escs">DroneCAN ESCs</a> are connected via the DroneCAN bus (setup and configuration are covered at that link).</p><h2 id="pwm" tabindex="-1">PWM <a class="header-anchor" href="#pwm" aria-label="Permalink to &quot;PWM&quot;">​</a></h2><p><a href="./../peripherals/pwm_escs_and_servo">PWM ESCs</a> are commonly used for fixed-wing vehicles and ground vehicles (vehicles that require a lower latency like multicopters typically use oneshot or dshot ESCs).</p><p>PWM ESCs communicate using a periodic pulse, where the <em>width</em> of the pulse indicates the desired speed. The pulse width typically ranges between 1000 μs for zero power and 2000 μs for full power. The periodic frame rate of the signal depends on the capability of the ESC, and commonly ranges between 50 Hz and 490 Hz (the theoretical maximum being 500 Hz for a very small &quot;off&quot; cycle). A higher rate is better for ESCs, in particular where a rapid response to setpoint changes is needed. For PWM servos 50 Hz is usually sufficient, and many don&#39;t support higher rates.</p><p><img src="'+a+'" alt="duty cycle for PWM"></p><p>In addition to being a relatively slow protocol PWM ESCs require <a href="./../advanced_config/esc_calibration">calibration</a> because the pulse widths representing low and high values can vary significantly. Unlike <a href="#dshot">DShot</a> and <a href="#dronecan">DroneCAN ESC</a> they do not have the ability to provide telemetry and feedback on ESC (or servo) state.</p><p>Setup:</p><ul><li><a href="./../peripherals/pwm_escs_and_servo">ESC Wiring</a></li><li><a href="./../peripherals/pwm_escs_and_servo#px4-configuration">PX4 Configuration</a></li><li><a href="./../advanced_config/esc_calibration">ESC Calibration</a></li></ul><h2 id="oneshot-125" tabindex="-1">OneShot 125 <a class="header-anchor" href="#oneshot-125" aria-label="Permalink to &quot;OneShot 125&quot;">​</a></h2><p><a href="./../peripherals/oneshot">OneShot 125 ESCs</a> are usually much faster than PWM ESCs, and hence more responsive and easier to tune. They are preferred over PWM for multicopters (but not as much as <a href="#dshot">DShot ESCs</a>, which do not require calibration, and may provide telemetry feedback). There are a number of variants of the OneShot protocol, which support different rates. PX4 only supports OneShot 125.</p><p>OneShot 125 is the same as PWM but uses pulse widths that are 8 times shorter (from 125 μs to 250 μs for zero to full power). This allows OneShot 125 ESCs to have a much shorter duty cycle/higher rate. For PWM the theoretical maximum is close to 500 Hz while for OneShot it approaches 4 kHz. The actual supported rate depends on the ESC used.</p><p>Setup:</p><ul><li><a href="./../peripherals/pwm_escs_and_servo">ESC Wiring</a> (same as for PWM ESCs)</li><li><a href="./../peripherals/oneshot#px4-configuration">PX4 Configuration</a></li><li><a href="./../advanced_config/esc_calibration">ESC Calibration</a></li></ul>',24)])])}const S=o(i,[["render",n]]);export{m as __pageData,S as default};
